const triggerItems = $items("When Executed by Another Workflow", 0, 0);
const trigger = (triggerItems && triggerItems[0] && triggerItems[0].json) || {};
const ctx = $json || {};
const context = ctx.context || {};
const messages = Array.isArray(ctx.messages) ? ctx.messages : [];

const contextOk =
  messages.length > 0 &&
  messages[0] &&
  typeof messages[0].content === "string" &&
  messages[0].content.trim().length > 0;

const currentMessage = typeof trigger.current_message === "string" ? trigger.current_message : "";
const trimmedCurrent = currentMessage.trim();
const hasArabic = /[\u0600-\u06FF]/.test(currentMessage);

// System message: built by /api/ai-context (format v3 -> promptBuilderV3).
// A degraded turn still gets a valid, JSON-only instruction.
const systemMessage = contextOk
  ? messages[0].content
  : [
      "You are the AI assistant for this business. Reply briefly and naturally in the customer's language.",
      "The business profile and knowledge base could not be loaded this turn — do not state any specific price, product detail, branch, address or opening time; if asked, say you will check with the team.",
      'Respond with ONE JSON object and nothing else: {"action":"reply","reply":"<your reply>","action_params":{},"options":[],"intent":"unknown"}.'
    ].join("\n");

// Recent transcript (both roles) -> one agent_input string, current message last, once.
let convo = messages
  .slice(1)
  .filter((m) => m && (m.role === "user" || m.role === "assistant") && typeof m.content === "string" && m.content.trim())
  .map((m) => ({ role: m.role, content: m.content.trim() }));
if (convo.length && convo[convo.length - 1].role === "user" && convo[convo.length - 1].content === trimmedCurrent) {
  convo = convo.slice(0, -1);
}
const agentInput = convo.length
  ? [
      "Conversation so far (context only \u2014 your earlier replies are not authoritative for facts):",
      ...convo.map((m) => (m.role === "assistant" ? "You: " : "Customer: ") + m.content),
      "",
      "Current customer message:",
      currentMessage
    ].join("\n")
  : currentMessage;

const fallbackReply = hasArabic
  ? "\u0622\u0633\u0641\u064a\u0646\u060c \u0635\u0627\u0631 \u0639\u0646\u0627 \u062e\u0644\u0644 \u062a\u0642\u0646\u064a \u0628\u0633\u064a\u0637 \u0647\u0644\u0642. \u0645\u0645\u0643\u0646 \u062a\u0628\u0639\u062a \u0631\u0633\u0627\u0644\u062a\u0643 \u0645\u0631\u0629 \u062a\u0627\u0646\u064a\u0629 \u0628\u0639\u062f \u0634\u0648\u064a\u061f"
  : "Sorry \u2014 we hit a brief technical issue on our side. Could you send your message again shortly?";

return [
  {
    json: {
      conversation_id: trigger.conversation_id || null,
      client_id: trigger.client_id || null,
      message_id: trigger.message_id || null,
      channel: trigger.channel || null,
      current_message: currentMessage,
      system_message: systemMessage,
      agent_input: agentInput,
      context_ok: contextOk,
      current_step: (context.conversation && context.conversation.current_step) || null,
      fallback_reply: fallbackReply
    }
  }
];

