// AI Engine V3 \u2014 validate the ONE structured object the Agent returned.
// Inline equivalent of api/_lib/agentResultV3.js validateAgentResultV3
// (kept in sync by api/_lib/__tests__/aiEngineV3.test.js). Any failure
// degrades to a plain "reply" \u2014 NEVER a close / handover / save on
// uncertainty. The backend (apply_agent_action_v3) re-validates too.
const prep = ($items("Prepare Agent Context", 0, 0)[0] || {}).json || {};
const agent = $json || {};

const V3_ACTIONS = ["reply", "handover", "save_contact", "request_confirmation", "close_conversation"];
const MAX_REPLY = 4000, MAX_OPT = 40, MAX_OPTS = 3, MAX_PARAM = 400;
const str = (v, max) => (typeof v === "string" ? v.trim().slice(0, max) : "");

let raw = agent.output;
if (raw == null) raw = agent.text != null ? agent.text : agent.response;

let obj = raw;
if (typeof raw === "string") {
  const s = raw.trim();
  const a = s.indexOf("{");
  const b = s.lastIndexOf("}");
  if (a !== -1 && b !== -1 && b > a) {
    try { obj = JSON.parse(s.slice(a, b + 1)); } catch (e) { obj = null; }
  } else {
    obj = null;
  }
}

const safeReply = (text) => ({
  action: "reply",
  reply: text || prep.fallback_reply || "",
  action_params: {},
  options: [],
  intent: "unknown"
});

if (!obj || typeof obj !== "object" || Array.isArray(obj)) {
  return [{ json: safeReply(typeof raw === "string" ? raw.trim() : "") }];
}

const reply = str(obj.reply != null ? obj.reply : obj.message != null ? obj.message : obj.text, MAX_REPLY);

let action = typeof obj.action === "string" ? obj.action.trim().toLowerCase() : "reply";
if (!V3_ACTIONS.includes(action)) action = "reply";

if (action !== "reply" && !reply) {
  return [{ json: safeReply("") }];
}

const rp =
  obj.action_params && typeof obj.action_params === "object" && !Array.isArray(obj.action_params)
    ? obj.action_params
    : {};
const action_params = {};
for (const k of ["name", "phone", "reason"]) {
  const v = str(rp[k], MAX_PARAM);
  if (v) action_params[k] = v;
}

const options = [];
for (const o of Array.isArray(obj.options) ? obj.options : []) {
  const v = str(o, MAX_OPT);
  if (v) options.push(v);
  if (options.length >= MAX_OPTS) break;
}

return [
  {
    json: {
      action,
      reply: reply || prep.fallback_reply || "",
      action_params,
      options,
      intent: str(obj.intent, 60) || "unknown"
    }
  }
];
